"""
4-colouring of complete graphs without monochromatic triangles.
Uses GF(64) multiplicative group structure to generate a 63-vertex candidate,
then prunes to the largest induced subgraph with no monochromatic triangles.
"""
import time

def construct():
    start_time = time.time()
    deadline = start_time + 115.0

    # GF(64) arithmetic: field generated by x^6 + x + 1
    # Elements are 6-bit integers 0..63
    def gf64_mul(a, b):
        r = 0
        for i in range(6):
            if (b >> i) & 1:
                r ^= a << i
        # Reduce modulo x^6 + x + 1 = 0b1000011
        for i in range(11, 5, -1):
            if (r >> i) & 1:
                r ^= 0b1000011 << (i - 6)
        return r

    # Build log/antilog tables using primitive element 2
    log = [0] * 64
    antilog = [0] * 64
    x = 1
    for e in range(63):
        log[x] = e
        antilog[e] = x
        x = gf64_mul(x, 2)
    # x should be back to 1 after 63 steps

    # The 63 nonzero elements form a cyclic group of order 63 = 7 * 9
    # We want to partition into 4 color classes such that no color class contains a triangle
    # Strategy: use the group structure. For vertices a, b (nonzero), color edge (a,b) 
    # based on log(a*b^(-1)) mod something.
    # 
    # Key insight: if we define color(i,j) = f(log(i) - log(j) mod 63), then a triangle 
    # (i,j,k) in color c means f(log(i)-log(j)), f(log(j)-log(k)), f(log(k)-log(i)) all = c.
    # Since log(i)-log(j) + log(j)-log(k) + log(k)-log(i) = 0 mod 63, we need to ensure
    # that there are no three values x, y, z with x+y+z = 0 mod 63 and f(x)=f(y)=f(z)=c.
    #
    # This is equivalent to finding a 4-coloring of Z_63 such that no color class contains
    # a Schur triple (x, y, x+y) where x+y is the third element.
    #
    # Let's use the fact that 63 = 7 * 9. We can use a homomorphism to Z_7 and Z_9.
    # For color assignment, use: color = (log(i)-log(j)) mod 7, but we need 4 colors.
    #
    # Alternative: Use the quadratic/cubic character approach.
    # In GF(64), the multiplicative group has order 63. 
    # 63 = 7 * 9 = 7 * 3^2
    # We can use characters of order 7 and 9.
    #
    # Let's try: color(i,j) = floor(((log(i) - log(j)) % 63) / 15.75)
    # This divides 63 into 4 roughly equal parts: [0,15], [16,31], [32,47], [48,62]
    # But this likely has triangles.
    #
    # Better approach: Use the fact that we need a sum-free set for each color.
    # A subset S of Z_n is sum-free if there are no x, y, z in S with x + y = z.
    # For Z_63, we need 4 sum-free sets that partition Z_63.
    #
    # Known construction: For Z_(2k+1), the set {k+1, ..., 2k} is sum-free.
    # For Z_63, {32, ..., 62} is sum-free (size 31).
    # We need 4 disjoint sum-free sets covering all 63 elements.
    #
    # Let's use a greedy approach with backtracking to find 4 sum-free sets in Z_63.

    # First, let's try a simple construction based on the group structure.
    # Use the decomposition 63 = 7 * 9.
    # Map each element g in Z_63 to (g mod 7, g mod 9) in Z_7 x Z_9.
    # Color based on g mod 7, but we only have 4 colors, not 7.
    #
    # Alternative: Use the quadratic character in GF(64).
    # An element x in GF(64)* is a square if and only if x^31 = 1.
    # The squares form a subgroup of order 31.
    # We can use: color 0 if x is a square, color 1 if not.
    # But we need 4 colors.
    #
    # Let's use: color(i,j) = (log(i) - log(j)) % 4
    # This is a homomorphism from Z_63 to Z_4.
    # Check: if (a-b)%4 = (b-c)%4 = (c-a)%4 = 0, then a≡b≡c mod 4, so a-b, b-c, c-a all ≡ 0 mod 4.
    # But a-b + b-c + c-a = 0, which is consistent. So this DOES have monochromatic triangles!
    #
    # We need a different approach. Let's use a proper sum-free partition.
    #
    # For Z_63, let's try:
    # Color 0: {1, 2, 4, 8, 16, 32, 64%63=1} - wait, that's the subgroup of order 6.
    #
    # Let me just do a backtracking search for a valid 4-coloring of Z_63.

    def find_sum_free_partition(n, k, deadline):
        """Find k sum-free subsets that partition Z_n."""
        # A subset S is sum-free if for all x, y in S, x+y mod n is not in S.
        # We need to assign each element of Z_n to one of k colors such that
        # each color class is sum-free.
        
        # Precompute for each element x and color c, which other elements would
        # conflict if x were assigned color c.
        # If x has color c, then for any y with color c, (x+y)%n must NOT have color c.
        
        assignment = [-1] * n
        order = list(range(n))
        
        def backtrack(idx):
            if time.time() > deadline:
                return None
            if idx == n:
                return assignment[:]
            x = order[idx]
            for c in range(k):
                # Check if assigning x to color c is consistent
                valid = True
                for y in range(n):
                    if assignment[y] == c:
                        z = (x + y) % n
                        if assignment[z] == c:
                            valid = False
                            break
                        # Also check if z is unassigned but would be forced
                        # Actually, we just need to check already-assigned elements
                if valid:
                    assignment[x] = c
                    res = backtrack(idx + 1)
                    if res is not None:
                        return res
                    assignment[x] = -1
            return None
        
        return backtrack(0)

    # The above backtracking is too slow for n=63. Let's use a smarter approach.
    # Use the known fact that Z_(2k+1) has a sum-free set of size k.
    # For Z_63, {32,33,...,62} is sum-free (size 31).
    # Remove that, and try to partition the remaining {0,1,...,31} into 3 sum-free sets.
    
    # Actually, let's use a different strategy: construct the coloring directly
    # using the algebraic structure and verify/prune.
    
    # Simple construction: color(i,j) = ((log(i) - log(j)) % 63) // 16
    # This gives 4 colors: 0 for [0,15], 1 for [16,31], 2 for [32,47], 3 for [48,62]
    # This likely has triangles, so we'll need to prune.
    
    # Let's generate the 63-vertex coloring and then find the largest triangle-free induced subgraph.
    
    def color_edge(a, b):
        """Color edge between nonzero GF(64) elements a and b."""
        if a == 0 or b == 0:
            return 0
        diff = (log[a] - log[b]) % 63
        return diff // 16  # 4 colors: 0,1,2,3
    
    # Build the full 63-vertex graph
    vertices = list(range(1, 64))  # 63 nonzero elements
    n_verts = len(vertices)
    
    # Build color matrix
    color_matrix = [[0] * n_verts for _ in range(n_verts)]
    for i in range(n_verts):
        for j in range(i + 1, n_verts):
            c = color_edge(vertices[i], vertices[j])
            color_matrix[i][j] = c
            color_matrix[j][i] = c
    
    # Find monochromatic triangles and remove vertices to eliminate them
    # Greedy approach: repeatedly find a monochromatic triangle and remove one vertex from it
    
    # Build adjacency for each color
    adj = [set() for _ in range(4)]
    for i in range(n_verts):
        for j in range(i + 1, n_verts):
            c = color_matrix[i][j]
            adj[c].add((i, j))
    
    # Convert to adjacency lists per color
    adj_lists = [set() for _ in range(4)]
    for c in range(4):
        for (i, j) in adj[c]:
            adj_lists[c].add(i)
            adj_lists[c].add(j)
    
    # Actually, let's build proper adjacency lists
    adj_list = [[set() for _ in range(4)] for _ in range(n_verts)]
    for i in range(n_verts):
        for j in range(i + 1, n_verts):
            c = color_matrix[i][j]
            adj_list[i][c].add(j)
            adj_list[j][c].add(i)
    
    # Find all monochromatic triangles
    def find_all_mono_triangles(adj_list, n):
        triangles = set()
        for c in range(4):
            for i in range(n):
                for j in adj_list[i][c]:
                    if j <= i:
                        continue
                    common = adj_list[i][c] & adj_list[j][c]
                    for k in common:
                        if k > j:
                            triangles.add((i, j, k, c))
        return triangles
    
    # Iteratively remove vertices from monochromatic triangles
    active = [True] * n_verts
    removed = 0
    
    while time.time() < deadline - 5:
        # Find a monochromatic triangle among active vertices
        found = False
        for c in range(4):
            for i in range(n_verts):
                if not active[i]:
                    continue
                for j in adj_list[i][c]:
                    if j <= i or not active[j]:
                        continue
                    for k in adj_list[i][c]:
                        if k <= j or not active[k]:
                            continue
                        if k in adj_list[j][c]:
                            # Found triangle (i, j, k) in color c
                            # Remove the vertex with the most edges in this color
                            deg_i = sum(1 for x in adj_list[i][c] if active[x])
                            deg_j = sum(1 for x in adj_list[j][c] if active[x])
                            deg_k = sum(1 for x in adj_list[k][c] if active[x])
                            if deg_i >= deg_j and deg_i >= deg_k:
                                active[i] = False
                            elif deg_j >= deg_i and deg_j >= deg_k:
                                active[j] = False
                            else:
                                active[k] = False
                            found = True
                            removed += 1
                            break
                    if found:
                        break
                if found:
                    break
            if found:
                break
        if not found:
            break
    
    # Count active vertices
    active_indices = [i for i in range(n_verts) if active[i]]
    n_final = len(active_indices)
    
    if n_final < 32:
        # Fallback to the K32 construction
        # GF(16) based construction
        def gf16_mul(a, b):
            r = 0
            for i in range(4):
                if (b >> i) & 1:
                    r ^= a << i
            for i in range(7, 3, -1):
                if (r >> i) & 1:
                    r ^= 0b10011 << (i - 4)
            return r
        
        log16 = {}
        x = 1
        for e in range(15):
            log16[x] = e
            x = gf16_mul(x, 2)
        
        colors = []
        for i in range(32):
            for j in range(i + 1, 32):
                if i // 16 == j // 16:
                    colors.append(log16[i ^ j] % 3)
                else:
                    colors.append(3)
        return {'n': 32, 'colors': colors}
    
    # Build the final coloring
    colors = []
    for idx_i in range(n_final):
        for idx_j in range(idx_i + 1, n_final):
            i = active_indices[idx_i]
            j = active_indices[idx_j]
            colors.append(color_matrix[i][j])
    
    return {'n': n_final, 'colors': colors}
